// n8n Function node code

// 1) Extrai o registro do Airtable
const input = items[0].json;

// 2) Valida arrays de cenas (imagens + áudios)
const imageUrls = input["url_s3_image (from Cenas)"];
const audioUrls = input["url_s3_audio (from Cenas)"];
const sceneTexts = input["Texto_Cena (from Cenas)"];

if (
  !Array.isArray(imageUrls) ||
  !Array.isArray(audioUrls) ||
  imageUrls.length === 0 ||
  imageUrls.length !== audioUrls.length
) {
  return [{ json: { error: "Invalid or missing scene data (images or audios)" } }];
}

// 3) Monta o array de cenas
const scenes = imageUrls.map((imageUrl, index) => {
  const scene = {
    image_url: imageUrl,
    audio_url: audioUrls[index],
  };
  if (Array.isArray(sceneTexts) && sceneTexts[index]) {
    scene.text = sceneTexts[index];
  }
  return scene;
});

// 4) Monta opções avançadas globais a partir dos campos de canal
const advancedOptions = {};

// Overlay
if (Array.isArray(input["Video_Overlay_URL (from Canal)"]) && input["Video_Overlay_URL (from Canal)"].length) {
  advancedOptions.overlay = {
    url: input["Video_Overlay_URL (from Canal)"][0],
    position: Array.isArray(input["Video_Overlay_Posicao (from Canal)"])
      ? input["Video_Overlay_Posicao (from Canal)"][0]
      : "Centro",
    opacity: Array.isArray(input["Video_Overlay_Opacidade (from Canal)"])
      ? input["Video_Overlay_Opacidade (from Canal)"][0]
      : 100,
  };
}

// Zoom
if (Array.isArray(input["Video_Zoom_Padrao (from Canal)"]) && input["Video_Zoom_Padrao (from Canal)"].length) {
  advancedOptions.zoom = {
    type: input["Video_Zoom_Padrao (from Canal)"][0],
    speed: Array.isArray(input["Video_Zoom_Velocidade (from Canal)"])
      ? input["Video_Zoom_Velocidade (from Canal)"][0]
      : 1,
  };
}

// Transitions
if (Array.isArray(input["Video_Transicoes_Tipo (from Canal)"]) && input["Video_Transicoes_Tipo (from Canal)"].length) {
  advancedOptions.transitions = {
    type: input["Video_Transicoes_Tipo (from Canal)"][0],
    duration: Array.isArray(input["Video_Transicoes_Duracao (from Canal)"])
      ? input["Video_Transicoes_Duracao (from Canal)"][0]
      : 1,
  };
}

// Captions
if (Array.isArray(input["Video_Legendas_Estilo (from Canal)"]) && input["Video_Legendas_Estilo (from Canal)"].length) {
  advancedOptions.captions = {
    enabled: true,
    style: input["Video_Legendas_Estilo (from Canal)"][0],
  };
}

// 5) Monta o payload final
const payload = {
  id: input["Record_ID_Airtable"] || "",
  title: input["Tema Name"] || "",
  scenes,
  webhook_url: input.webhook_url || "https://api.paradox8.com/webhook/get-render-video",
};

if (Object.keys(advancedOptions).length) {
  payload.advanced_options = advancedOptions;
}

// 6) Retorna para o próximo nó HTTP Request
return [{ json: payload }];
